─────────────────────────────────────────────────────────────────────────────*/

const DEG = THREE.MathUtils.degToRad;

/* ── lights + tiny environment (metal + glass need reflections) ───────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.55));
scene.add(new THREE.HemisphereLight(0xffffff, 0x9aa0a6, 0.55));
const keyL = new THREE.DirectionalLight(0xffffff, 0.85); keyL.position.set(5, 7, 8); scene.add(keyL);
const fillL = new THREE.DirectionalLight(0xffffff, 0.35); fillL.position.set(-7, 3, -5); scene.add(fillL);

function makeCanvas(w, h, draw) {
  const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
  const ctx = cv.getContext('2d'); draw(ctx, cv);
  const tex = new THREE.CanvasTexture(cv); tex.anisotropy = 4; tex.needsUpdate = true;
  return { cv, ctx, tex };
}

(function buildEnv() {
  const e = makeCanvas(256, 128, (ctx) => {
    const g = ctx.createLinearGradient(0, 0, 0, 128);
    g.addColorStop(0, '#ffffff'); g.addColorStop(0.5, '#dfe3e8'); g.addColorStop(1, '#8f949a');
    ctx.fillStyle = g; ctx.fillRect(0, 0, 256, 128);
    ctx.fillStyle = 'rgba(255,255,255,0.9)'; ctx.fillRect(40, 10, 50, 40);
  });
