  const pm = new THREE.PMREMGenerator(renderer);
  scene.environment = pm.fromEquirectangular(e.tex).texture;
  pm.dispose();
})();

/* ── CENTER: tube, sample, coil, collars ─────────────────────────────────── */
const coilGroup = new THREE.Group(); scene.add(coilGroup);

const glassMat = new THREE.MeshPhysicalMaterial({
  color: 0xBFE3F5, roughness: 0.06, metalness: 0.0, transmission: 0.88, thickness: 0.35,
  ior: 1.5, transparent: true, opacity: 0.45, depthWrite: false, side: THREE.DoubleSide
});
const tube = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.28, 4.6, 40, 1, true), glassMat);
tube.renderOrder = 12; coilGroup.add(tube);
const tubeBottom = new THREE.Mesh(
  new THREE.SphereGeometry(0.28, 32, 16, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), glassMat);
tubeBottom.position.y = -2.3; tubeBottom.renderOrder = 12; coilGroup.add(tubeBottom);
const tubeLip = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.28, 0.26, 40, 1, true), glassMat);
tubeLip.position.y = 2.42; tubeLip.renderOrder = 12; coilGroup.add(tubeLip);

const sampleMat = new THREE.MeshStandardMaterial({
  color: 0xE8A33D, roughness: 0.45, metalness: 0.05, emissive: 0xE8731D, emissiveIntensity: 0.0
});
const sample = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.2, 2.6, 32), sampleMat);
sample.position.y = -0.3; coilGroup.add(sample);
const sampleCapMat = new THREE.MeshStandardMaterial({ color: 0xD98F2A, roughness: 0.5 });
const sampleBot = new THREE.Mesh(new THREE.SphereGeometry(0.2, 24, 12, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), sampleCapMat);
sampleBot.position.y = -1.6; coilGroup.add(sampleBot);
const stripe = new THREE.Mesh(
  new THREE.CylinderGeometry(0.206, 0.206, 2.5, 20, 1, true, -0.35, 0.7),
  new THREE.MeshStandardMaterial({ color: 0xF5C77E, roughness: 0.35, side: THREE.DoubleSide }));
stripe.position.set(0, -0.3, 0); coilGroup.add(stripe);

// green helix coil
const helixPts = [];
const TURNS = 22, Y0 = -1.1, Y1 = 0.9, RC = 0.42;
for (let i = 0; i <= TURNS * 24; i++) {
  const u = i / (TURNS * 24), a = u * TURNS * Math.PI * 2;
  helixPts.push(new THREE.Vector3(RC * Math.cos(a), Y0 + (Y1 - Y0) * u, RC * Math.sin(a)));
}
const coilCurve = new THREE.CatmullRomCurve3(helixPts);
const coilMat = new THREE.MeshStandardMaterial({ color: 0x4CAF3E, roughness: 0.4, metalness: 0.15, emissive: 0x1f5a18, emissiveIntensity: 0 });
const coil = new THREE.Mesh(new THREE.TubeGeometry(coilCurve, TURNS * 24, 0.042, 10, false), coilMat);
coilGroup.add(coil);

const collarMat = new THREE.MeshStandardMaterial({ color: 0x1E6FB8, roughness: 0.35, metalness: 0.2 });
const collarTop = new THREE.Mesh(new THREE.CylinderGeometry(0.48, 0.48, 0.25, 32), collarMat.clone());
collarTop.position.y = 1.0; coilGroup.add(collarTop);
const collarBot = new THREE.Mesh(new THREE.CylinderGeometry(0.48, 0.48, 0.25, 32), collarMat.clone());
