/* ── UPDATE LOOP ─────────────────────────────────────────────────────────── */
let lastT = performance.now(), flash = 0, clock = 0, lastDrawKey = '';
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - lastT) / 1000); lastT = now; clock += dt;

  if (fieldTween) {
    fieldTween.t += dt;
    const u = Math.min(1, fieldTween.t / fieldTween.dur);
    const e = u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2;
    setField(fieldTween.from + (fieldTween.to - fieldTween.from) * e, true);
    if (u >= 1) fieldTween = null;
  }

  // peaks accumulate as the sweep passes each resonance
  let changed = false;
  for (let i = 0; i < RES.length; i++) {
    const tgt = B0 >= RES[i].B - 0.005 ? 1 : 0;
    const nv = peakAmt[i] + (tgt - peakAmt[i]) * Math.min(1, dt * 5);
    if (Math.abs(nv - peakAmt[i]) > 0.0015) changed = true;
    peakAmt[i] = nv;
  }

  // resonance detection
  let near = null, dmin = 1e9;
  RES.forEach((r, i) => { const dd = Math.abs(B0 - r.B); if (dd < dmin) { dmin = dd; near = i; } });
  const onRes = dmin < 0.03;
  flash += ((onRes ? 1 : 0) - flash) * Math.min(1, dt * 8);
  const pulse = 0.55 + 0.45 * Math.sin(clock * 9);
  sampleMat.emissiveIntensity = flash * 1.2 * pulse;
  coilMat.emissiveIntensity = flash * 0.9 * pulse;
  const ph = (clock * 1.2) % 1;
  flashSphere.scale.setScalar(0.7 + ph * 1.6);
  flashSphere.material.opacity = flash * 0.30 * (1 - ph);

  resStatus.innerHTML = onRes
    ? '<b style="color:#c06000">RESONANCE</b> — nuclei at B₀ ≈ ' + RES[near].B.toFixed(2) + ' T absorb; peak ' + (near + 1) + ' is written.'
    : 'off resonance — ν ≠ γB₀/2π, no absorption (next event at ' +
      (RES.find(r => r.B > B0) ? RES.find(r => r.B > B0).B.toFixed(2) + ' T)' : 'none above)');

  // highlight
  Object.keys(PARTS).forEach(k => {
    const on = selected === k;
    PARTS[k].meshes.forEach(rec => {
      const want = on ? 0.35 + 0.25 * pulse : rec.baseI;
      rec.mesh.material.emissive.setHex(on ? 0xffd166 : rec.base);
      rec.mesh.material.emissiveIntensity = on ? want : rec.baseI;
    });
  });
  allCables.forEach(c => { c.material.emissiveIntensity = 0; });
  if (selected && PARTS[selected]) {
    PARTS[selected].cables.forEach(c => { c.material.emissiveIntensity = 0.45 + 0.4 * pulse; });
  }

  const key = peakAmt.map(v => v.toFixed(2)).join(',') + '|' + B0.toFixed(2);
  if (changed || key !== lastDrawKey) { drawSpectrum(); lastDrawKey = key; }
}
tick();
